CREATE TABLE organizations(id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data))) STRICT;
CREATE TABLE projects(org_id TEXT NOT NULL,id TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(org_id,id),FOREIGN KEY(org_id) REFERENCES organizations(id)) STRICT;
CREATE TABLE applications(org_id TEXT NOT NULL,id TEXT NOT NULL,project_id TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,project_id),FOREIGN KEY(org_id,project_id) REFERENCES projects(org_id,id)) STRICT;
CREATE TABLE flavors(org_id TEXT NOT NULL,id TEXT NOT NULL,app_id TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,app_id),FOREIGN KEY(org_id,app_id) REFERENCES applications(org_id,id)) STRICT;
CREATE TABLE environments(org_id TEXT NOT NULL,id TEXT NOT NULL,app_id TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,app_id),FOREIGN KEY(org_id,app_id) REFERENCES applications(org_id,id)) STRICT;
CREATE TABLE platform_targets(org_id TEXT NOT NULL,id TEXT NOT NULL,project_id TEXT NOT NULL,app_id TEXT NOT NULL,flavor_id TEXT NOT NULL,environment_id TEXT NOT NULL,platform TEXT NOT NULL CHECK(platform IN ('ios','android','web')),data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,app_id),UNIQUE(org_id,app_id,flavor_id,environment_id,platform),FOREIGN KEY(org_id,app_id,project_id) REFERENCES applications(org_id,id,project_id),FOREIGN KEY(org_id,flavor_id,app_id) REFERENCES flavors(org_id,id,app_id),FOREIGN KEY(org_id,environment_id,app_id) REFERENCES environments(org_id,id,app_id)) STRICT;
CREATE TABLE source_revisions(org_id TEXT NOT NULL,id TEXT NOT NULL,app_id TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,app_id),FOREIGN KEY(org_id,app_id) REFERENCES applications(org_id,id)) STRICT;
CREATE TABLE config_snapshots(org_id TEXT NOT NULL,id TEXT NOT NULL,app_id TEXT NOT NULL,target_id TEXT NOT NULL,source_id TEXT NOT NULL,digest TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,target_id,source_id),FOREIGN KEY(org_id,target_id,app_id) REFERENCES platform_targets(org_id,id,app_id),FOREIGN KEY(org_id,source_id,app_id) REFERENCES source_revisions(org_id,id,app_id)) STRICT;
CREATE TABLE snapshot_references(org_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,key TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('SECRET','FILE','CREDENTIAL')),resource_id TEXT NOT NULL,version_id TEXT NOT NULL,PRIMARY KEY(org_id,snapshot_id,key),FOREIGN KEY(org_id,snapshot_id) REFERENCES config_snapshots(org_id,id)) STRICT;
CREATE TABLE releases(org_id TEXT NOT NULL,id TEXT NOT NULL,app_id TEXT NOT NULL,source_id TEXT NOT NULL,data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(org_id,id),UNIQUE(org_id,id,source_id),FOREIGN KEY(org_id,source_id,app_id) REFERENCES source_revisions(org_id,id,app_id)) STRICT;
CREATE TABLE jobs(org_id TEXT NOT NULL,id TEXT NOT NULL,release_id TEXT NOT NULL,target_id TEXT NOT NULL,source_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('build','store_submit','store_release')),idempotency_key TEXT NOT NULL,request_digest TEXT NOT NULL,request_data TEXT NOT NULL CHECK(json_valid(request_data)),status TEXT NOT NULL CHECK(status IN ('queued','assigned','running','waiting','success','failed','cancelled','expired')),attempt_count INTEGER NOT NULL DEFAULT 0 CHECK(attempt_count>=0 AND attempt_count<=3),current_attempt_id TEXT,fence INTEGER NOT NULL DEFAULT 0 CHECK(fence>=0),lease_until INTEGER,waiting_reason TEXT,result_digest TEXT,artifact_id TEXT,PRIMARY KEY(org_id,id),UNIQUE(org_id,idempotency_key),UNIQUE(org_id,id,release_id,target_id,source_id,snapshot_id),FOREIGN KEY(org_id,release_id,source_id) REFERENCES releases(org_id,id,source_id),FOREIGN KEY(org_id,snapshot_id,target_id,source_id) REFERENCES config_snapshots(org_id,id,target_id,source_id)) STRICT;
CREATE TABLE job_attempts(org_id TEXT NOT NULL,id TEXT NOT NULL,job_id TEXT NOT NULL,runner_id TEXT NOT NULL,fence INTEGER NOT NULL CHECK(fence>0),expires_at INTEGER NOT NULL,lease_duration INTEGER NOT NULL CHECK(lease_duration BETWEEN 5000 AND 120000),status TEXT NOT NULL CHECK(status IN ('assigned','running','success','failed','cancelled','expired')),result_digest TEXT,PRIMARY KEY(org_id,id),UNIQUE(org_id,id,job_id),UNIQUE(org_id,job_id,fence),FOREIGN KEY(org_id,job_id) REFERENCES jobs(org_id,id)) STRICT;
CREATE TABLE artifacts(org_id TEXT NOT NULL,id TEXT NOT NULL,job_id TEXT NOT NULL,attempt_id TEXT NOT NULL,release_id TEXT NOT NULL,target_id TEXT NOT NULL,source_id TEXT NOT NULL,snapshot_id TEXT NOT NULL,digest TEXT NOT NULL,size_bytes INTEGER NOT NULL CHECK(size_bytes>=0),data TEXT NOT NULL CHECK(json_valid(data)),PRIMARY KEY(org_id,id),UNIQUE(org_id,job_id,attempt_id),FOREIGN KEY(org_id,attempt_id,job_id) REFERENCES job_attempts(org_id,id,job_id),FOREIGN KEY(org_id,job_id,release_id,target_id,source_id,snapshot_id) REFERENCES jobs(org_id,id,release_id,target_id,source_id,snapshot_id)) STRICT;
CREATE TABLE audit_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,org_id TEXT NOT NULL,job_id TEXT NOT NULL,actor_id TEXT NOT NULL,action TEXT NOT NULL,at INTEGER NOT NULL,attempt_id TEXT,fence INTEGER,safe_code TEXT,FOREIGN KEY(org_id,job_id) REFERENCES jobs(org_id,id)) STRICT;
CREATE INDEX jobs_expiry ON jobs(org_id,status,lease_until);
CREATE INDEX attempts_job ON job_attempts(org_id,job_id);
CREATE INDEX audit_job ON audit_events(org_id,job_id,sequence);
CREATE TRIGGER attempts_terminal_update BEFORE UPDATE ON job_attempts WHEN OLD.status IN ('success','failed','cancelled','expired') BEGIN SELECT RAISE(ABORT,'immutable attempt'); END;
CREATE TRIGGER attempts_delete BEFORE DELETE ON job_attempts BEGIN SELECT RAISE(ABORT,'immutable attempt'); END;
CREATE TRIGGER platform_targets_update BEFORE UPDATE ON platform_targets BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER platform_targets_delete BEFORE DELETE ON platform_targets BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER source_revisions_update BEFORE UPDATE ON source_revisions BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER source_revisions_delete BEFORE DELETE ON source_revisions BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER config_snapshots_update BEFORE UPDATE ON config_snapshots BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER config_snapshots_delete BEFORE DELETE ON config_snapshots BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER snapshot_references_update BEFORE UPDATE ON snapshot_references BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER snapshot_references_delete BEFORE DELETE ON snapshot_references BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER releases_update BEFORE UPDATE ON releases BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER releases_delete BEFORE DELETE ON releases BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER artifacts_update BEFORE UPDATE ON artifacts BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER artifacts_delete BEFORE DELETE ON artifacts BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER audit_events_update BEFORE UPDATE ON audit_events BEGIN SELECT RAISE(ABORT,'immutable record'); END;
CREATE TRIGGER audit_events_delete BEFORE DELETE ON audit_events BEGIN SELECT RAISE(ABORT,'immutable record'); END;
